def benchmark():
    flags=[1]*256
    for p in range(2,16):
        if flags[p]:
            for k in range(p*p,256,p): flags[k]=0
    return sum(flags[2:])

def towers(n):
    return 0 if n==0 else 1+towers(n-1)+towers(n-1)
def benchmark(): return towers(18)

def benchmark():
    cols=[0]*8
    def safe(row,col):
        return all(cols[p]!=col and abs(cols[p]-col)!=row-p for p in range(row))
    def place(row):
        if row==8: return 1
        total=0
        for col in range(8):
            if safe(row,col): cols[row]=col; total+=place(row+1)
        return total
    return place(0)

def benchmark():
    values=list(range(8))
    def permute(n):
        if n==1: return 1
        total=0
        for i in range(n):
            total+=permute(n-1); j=i if n%2==0 else 0; values[j],values[n-1]=values[n-1],values[j]
        return total
    return permute(8)

def ack(m,n):
    return n+1 if m==0 else ack(m-1,1) if n==0 else ack(m-1,ack(m,n-1))
def benchmark(): return ack(3,8)

def tak(x,y,z):
    return z if x<=y else tak(tak(x-1,y,z),tak(y-1,z,x),tak(z-1,x,y))
def benchmark(): return tak(18,12,6)

def benchmark():
    total=0
    for n in range(1,10001):
        steps=0
        while n!=1:
            n=n//2 if n%2==0 else 3*n+1; steps+=1
        total+=steps
    return total

def benchmark():
    a=list(range(1,17)); b=[1,4,7,10,13,16,2,5,8,11,14,0,3,6,9,12]; c=[0]*16
    for _ in range(100):
        for row in range(4):
            for col in range(4): c[row*4+col]=sum(a[row*4+k]*b[k*4+col] for k in range(4))
    return sum(c)
